## Problem 1 — run a program, capture everything

Edit `ex1/solution.ts`. Implement:

```ts
export interface CommandResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
}

export function runCommand(file: string, args: readonly string[]): Promise<CommandResult>
```

Spawn without a shell, collect both streams to completion, and resolve when
the child *and* its stdio are finished. Decode as UTF-8 only after you have
all the bytes. If the process cannot be started at all, reject with the
`error` event's error.

```ts
await runCommand(process.execPath, ["-e", "console.log('hi'); process.exit(2)"]);
// { code: 2, signal: null, stdout: "hi\n", stderr: "" }

await runCommand("definitely-not-a-real-binary", []);   // rejects, error.code === "ENOENT"
```

```
uv run dojo test node v3nc02_child_processes ex1
```

references.solution.ts:
// v3nc02_child_processes / ex1 - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";

export interface CommandResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
}

export function runCommand(file: string, args: readonly string[]): Promise<CommandResult> {
  return new Promise<CommandResult>((resolve, reject) => {
    // No shell: every element of `args` reaches the program verbatim.
    const child = spawn(file, [...args], { stdio: ["ignore", "pipe", "pipe"] });

    const out: Buffer[] = [];
    const err: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => out.push(chunk));
    child.stderr.on("data", (chunk: Buffer) => err.push(chunk));

    let settled = false;
    // "The binary was not there" is not a program failure - it is a rejection.
    child.once("error", (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    });

    // close, not exit: exit means the process is gone, close means its pipes
    // have ended too, and the last chunk lives in that gap.
    child.once("close", (code, signal) => {
      if (settled) return;
      settled = true;
      resolve({
        code,
        signal,
        // Decode once, at the end: a multi-byte character split across two
        // chunks is only correct when the bytes are joined first.
        stdout: Buffer.concat(out).toString("utf8"),
        stderr: Buffer.concat(err).toString("utf8"),
      });
    });
  });
}

