```

references.solution.ts:
// v3nc02_child_processes / ex4 - reference solution (author only, used by `dojo verify`).

export interface SpawnSpec {
  file: string;
  args: string[];
  shell: boolean;
}

// Refusal, not escaping: quoting rules differ between sh, cmd.exe and
// PowerShell, and every escaping implementation has eventually been bypassed.
const METACHARACTERS = /[;|&$`()<>\n\r]/;

export function planSpawn(input: {
  file: string;
  args: readonly string[];
  platform?: NodeJS.Platform;
}): SpawnSpec {
  const platform = input.platform ?? process.platform;
  if (input.file.length === 0) throw new RangeError("file must not be empty");

  if (METACHARACTERS.test(input.file)) {
    throw new Error(
      `file contains a shell metacharacter, which means someone built a command string: ${input.file}`,
    );
  }

  // Arguments are data. Without a shell they are handed to the program
  // verbatim, so "; rm -rf /" is a search string and nothing more.
  const args = [...input.args];

  // The one place a shell is unavoidable: Windows cannot execute a .cmd or
  // .bat except through cmd.exe (and Node has required this explicitly since
  // the April 2024 security releases).
  const isBatch = platform === "win32" && /\.(cmd|bat)$/i.test(input.file);

  return { file: input.file, args, shell: isBatch };
}

