## Problem 5 — request and response over IPC

Edit `ex5/solution.ts`. Implement:

```ts
export interface RpcChild {
  call<T>(method: string, params: unknown): Promise<T>;
  close(): Promise<void>;
}

export function createRpcChild(source: string): RpcChild
```

Spawn `process.execPath` with `["-e", source]` and
`stdio: ["ignore", "ignore", "ignore", "ipc"]`, then implement a
request/response protocol over `child.send` / `message`:

- each call gets a unique `id`; the child echoes it back;
- a reply `{ id, ok: true, value }` resolves that call, `{ id, ok: false,
  error }` rejects it with an `Error` carrying that message;
- **replies may arrive in any order** — correlate by id, never by arrival;
- if the child exits with calls outstanding, reject every one of them;
- `close()` disconnects the IPC channel and waits for the child to exit.

The child in the gate answers `{ id, ok: true, value: params }` after a
variable delay, so a solution that assumes FIFO fails.

```
uv run dojo test node v3nc02_child_processes ex5
```

references.solution.ts:
// v3nc02_child_processes / ex5 - reference solution (author only, used by `dojo verify`).
import { spawn, type ChildProcess } from "node:child_process";

export interface RpcChild {
  call<T>(method: string, params: unknown): Promise<T>;
  close(): Promise<void>;
}

interface Reply {
  id: number;
  ok: boolean;
  value?: unknown;
  error?: string;
}

export function createRpcChild(source: string): RpcChild {
  // The fourth stdio slot is the IPC channel fork() would have given us; spawn
  // can have it too, which lets the child be an -e one-liner.
  const child: ChildProcess = spawn(process.execPath, ["-e", source], {
    stdio: ["ignore", "ignore", "ignore", "ipc"],
  });

  const pending = new Map<number, { resolve: (v: never) => void; reject: (e: unknown) => void }>();
  let nextId = 1;
  let dead = false;

  child.on("message", (raw: Reply) => {
    // Correlate by id, never by arrival: the pipe is ordered, the child's work
    // is not, so replies come back in completion order.
    const waiter = pending.get(raw.id);
    if (!waiter) return;
    pending.delete(raw.id);
    if (raw.ok) waiter.resolve(raw.value as never);
    else waiter.reject(new Error(raw.error ?? "rpc call failed"));
  });

  const failAll = (reason: Error): void => {
    dead = true;
    for (const [, waiter] of pending) waiter.reject(reason);
    pending.clear();
  };

  child.once("error", (error) => failAll(error));
  // Every outstanding promise is now a promise nobody will ever settle.
  child.once("exit", (code, signal) =>
    failAll(new Error(`rpc child exited (code=${code}, signal=${signal}) with calls in flight`)),
  );

  return {
    call<T>(method: string, params: unknown): Promise<T> {
      if (dead || !child.connected) {
        return Promise.reject(new Error("rpc channel is closed"));
      }
      const id = nextId++;
      const { promise, resolve, reject } = Promise.withResolvers<T>();
      pending.set(id, { resolve: resolve as (v: never) => void, reject });
      child.send({ id, method, params });
      return promise;
    },

    close(): Promise<void> {
      return new Promise<void>((resolve) => {
        if (child.exitCode !== null || child.signalCode !== null) return resolve();
        child.once("exit", () => resolve());
        // Closing the channel is usually enough: it was the handle keeping an
        // idle child's event loop alive.
        if (child.connected) child.disconnect();
      });
    },
  };
}

exercises.hints:
## Hint 1

The shape from `d07_concurrency_control` transfers directly: a shared cursor,
N workers pulling the next index, each writing its result into
`results[index]`.

Writing into a slot rather than pushing is what makes the output order
positional and completion order irrelevant.

## Hint 2

```ts
let next = 0;
const worker = async (): Promise<void> => {
  while (next < specs.length) {
    const index = next++;
    results[index] = await runOne(specs[index]);
  }
};
await Promise.all(Array.from({ length: lanes }, worker));
```

`next++` is atomic here in a way it would not be with threads — there is one
JavaScript thread, and no `await` occurs between the read and the increment.

## Hint 3

Cap the lane count at `specs.length`; starting eight lanes for three specs
means five async functions that immediately return, which is harmless but
sloppy, and it hides an off-by-one if the loop condition is wrong.

The decision left to you: whether a lane should keep going after its command
fails. The spec says a failure is an outcome, not an exception — make sure
your `runOne` never rejects, or wrap it where it matters.

references.solution.ts:
// v3nc02_child_processes / ex6 - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";

export interface Spec {
  file: string;
  args: readonly string[];
}

export interface Outcome {
  code: number | null;
  stdout: string;
  error?: string;
}

function runOne(spec: Spec): Promise<Outcome> {
  return new Promise<Outcome>((resolve) => {
    const child = spawn(spec.file, [...spec.args], { stdio: ["ignore", "pipe", "ignore"] });
    const chunks: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => chunks.push(chunk));

    let settled = false;
    const finish = (outcome: Outcome): void => {
      if (settled) return;
      settled = true;
      resolve(outcome);
    };

    // A spawn failure is an outcome for this spec, not a failure of the batch.
    child.once("error", (error) => finish({ code: null, stdout: "", error: error.message }));
    child.once("close", (code) => finish({ code, stdout: Buffer.concat(chunks).toString("utf8") }));
  });
}

export async function runAll(
  specs: readonly Spec[],
  options: { concurrency: number },
): Promise<Outcome[]> {
  if (!Number.isInteger(options.concurrency) || options.concurrency < 1) {
    throw new RangeError(`concurrency must be a positive integer, got ${options.concurrency}`);
  }
  if (specs.length === 0) return [];

  const results = new Array<Outcome>(specs.length);
  let next = 0;

  const lane = async (): Promise<void> => {
    while (next < specs.length) {
      // One JS thread and no await between the read and the increment, so this
      // is a safe hand-rolled cursor.
      const index = next++;
      // Writing into the slot is what makes the output positional; pushing
      // would give completion order.
      results[index] = await runOne(specs[index]);
    }
  };

  const lanes = Math.min(options.concurrency, specs.length);
  await Promise.all(Array.from({ length: lanes }, lane));
  return results;
}

