```

references.solution.ts:
// v3nc02_child_processes / ex7 - reference solution (author only, used by `dojo verify`).

export type Outcome =
  | { kind: "ok" }
  | { kind: "nonzero"; code: number }
  | { kind: "signal"; signal: NodeJS.Signals }
  | { kind: "spawn-failed"; code: string; message: string };

export function classifyOutcome(input: {
  error?: NodeJS.ErrnoException;
  code: number | null;
  signal: NodeJS.Signals | null;
}): Outcome {
  // First, because a process that never started has a null code and a null
  // signal, and a code check would misread that as success.
  if (input.error) {
    return {
      kind: "spawn-failed",
      code: input.error.code ?? "UNKNOWN",
      message: input.error.message,
    };
  }
  // A killed process has no exit status at all: null is not zero.
  if (input.signal !== null) return { kind: "signal", signal: input.signal };
  if (input.code === 0) return { kind: "ok" };
  return { kind: "nonzero", code: input.code ?? -1 };
}

export function shouldRetry(outcome: Outcome): boolean {
  switch (outcome.kind) {
    case "ok":
      return false;
    // The program considered the input and disagreed. Running it again runs
    // the same disagreement.
    case "nonzero":
      return false;
    case "spawn-failed":
      // Transient resource exhaustion: the process table or the descriptor
      // limit is full now and may not be in a moment. ENOENT never resolves
      // itself.
      return outcome.code === "EAGAIN" || outcome.code === "EMFILE";
    case "signal":
      // SIGKILL is usually the OOM killer, which a retry under lighter load can
      // survive; SIGTERM is somebody deciding, and we respect decisions.
      return outcome.signal === "SIGKILL";
  }
}

// v3nc02_child_processes / ex8 - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";
import { once } from "node:events";

export interface PipeResult {
  stdout: string;
  // Chunks handed to write(), not chunks the child read: a chunk can still be
  // sitting in the pipe buffer when the reader dies.
  wrote: number;
  brokenPipe: boolean;
}

export async function pipeThrough(
  file: string,
  args: readonly string[],
  input: readonly string[],
): Promise<PipeResult> {
  const child = spawn(file, [...args], { stdio: ["pipe", "pipe", "ignore"] });

  // Start reading before writing: if both pipes fill while each side waits for
  // the other, neither process can make progress.
  const chunks: Buffer[] = [];
  child.stdout.on("data", (chunk: Buffer) => chunks.push(chunk));

  // An unhandled "error" on a stream is an uncaught exception, and EPIPE on a
  // child's stdin is an everyday event.
  let brokenPipe = false;
  child.stdin.on("error", (error: NodeJS.ErrnoException) => {
    if (error.code === "EPIPE") brokenPipe = true;
  });

  let wrote = 0;
  try {
    for (const chunk of input) {
      if (brokenPipe) break;
      if (!child.stdin.write(chunk)) {
        // once() rejects if the stream errors while we wait, so a dead reader
        // cannot leave this await pending for ever.
        await once(child.stdin, "drain");
      }
      wrote += 1;
    }
    if (!brokenPipe) child.stdin.end();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EPIPE") throw error;
    brokenPipe = true;
  }

  const [code] = (await once(child, "close")) as [number | null];
  void code;

  return { stdout: Buffer.concat(chunks).toString("utf8"), wrote, brokenPipe };
}

